head.script:
scwin.onpageload = function() {
    scwin.dlGridData = [{
            "lv1": "1",
        },
        {
            "lv1": "2",
        }
    ];
    scwin.dlCodeData = [{
            "lv1": "1",
            "lv2": "1-1",
            "label": "일-일"
        },
        {
            "lv1": "1",
            "lv2": "1-2",
            "label": "일-이"
        },
        {
            "lv1": "1",
            "lv2": "1-3",
            "label": "일-삼"
        },
        {
            "lv1": "2",
            "lv2": "2-1",
            "label": "이-일"
        },
        {
            "lv1": "2",
            "lv2": "2-2",
            "label": "이-이"
        },
        {
            "lv1": "2",
            "lv2": "2-3",
            "label": "이-삼"
        },
        {
            "lv1": "3",
            "lv2": "3-1",
            "label": "삼-일"
        },
        {
            "lv1": "3",
            "lv2": "3-2",
            "label": "삼-이"
        },
        {
            "lv1": "3",
            "lv2": "3-3",
            "label": "삼-삼"
        }
    ];
    dlCode.setJSON(scwin.dlCodeData);
    dlGrid.setJSON(scwin.dlGridData);
};
scwin.onpageunload = function() {};
scwin.btnAddRow_onclick = function(e) {
    dlGrid.insertRow(0);
};
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#autoComplete1_input', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById("grd_cell_1_0").getAttribute('readonly') == 'true';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'G_'+$p.id+'gvGridList1__lv1').value = 2");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_1_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'G_'+$p.id+'gvGridList1__lv1').value = 3");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_1_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gvGridList1_cell_1_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'G_'+$p.id+'gvGridList1___selectbox_lv2_2_gridViewItemTable_gridView_cell_1_1').innerText == '3-1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
